INSERT INTO `packages` VALUES (1,'Gói Khởi Đầu (Starter)','goi-khoi-dau-starter','Trải nghiệm 🚀','Phù hợp cho giáo viên chủ nhiệm trải nghiệm ôn luyện cho một lớp học trong 1 tháng.',390000,590000,30,35,'[\"Quản lý tối đa 35 học sinh\", \"Cấp quyền bài học & đề thi Khối 3\", \"Làm bài thi trắc nghiệm & mô phỏng tương tác\", \"Tự động chấm điểm & xếp loại chuẩn quốc tế\", \"Bảng vàng thi đua & báo cáo kết quả cơ bản\"]',1,1,'2026-09-17 07:43:48','2026-09-20 02:30:23'),(2,'Gói Tiêu Chuẩn (Standard)','goi-tieu-chuan-standard','Phổ biến nhất ⭐','Giải pháp tối ưu cho giáo viên giảng dạy nhiều lớp trong một học kỳ hoàn chỉnh.',990000,1490000,90,100,'[\"Quản lý tối đa 100 học sinh\", \"Mở khóa 2 Khối lớp (Khối 3 và Khối 4)\", \"Toàn bộ ngân hàng đề thi chuẩn IC3 GS6\", \"Khu trò chơi tích sao đổi quà & mini-game giáo dục\", \"Báo cáo phân tích chuyên sâu từng chủ đề\", \"Xuất kết quả bài thi ra tệp Excel / CSV\", \"Hỗ trợ kỹ thuật nhanh chóng\"]',1,2,'2026-09-17 07:43:48','2026-09-17 07:43:48'),(3,'Gói Trường Học Toàn Diện (Pro School)','goi-truong-hoc-toan-dien','Siêu tiết kiệm 🔥','Gói cao cấp dành cho trường học, trung tâm tin học và giáo viên phụ trách toàn trường cả năm học.',2490000,3800000,365,300,'[\"Quản lý tối đa 300 học sinh\", \"Mở khóa TOÀN BỘ 3 Khối lớp (Khối 3, 4, 5)\", \"Không giới hạn số lượt làm bài & thi thử\", \"Trợ lý AI phân tích điểm mạnh & lỗ hổng kiến thức\", \"Quyền truy cập Studio tùy chỉnh và tạo bộ đề riêng\", \"Cấu hình xáo trộn câu hỏi & bảo mật phòng thi\", \"Bàn giao hệ thống & Hỗ trợ kỹ thuật VIP 1-1\"]',1,3,'2026-09-17 07:43:48','2026-09-17 07:43:48'),(4,'Gói Bản Quyền Toàn Năng VIP (Enterprise)','goi-toan-nang-vip-enterprise','VIP Toàn Năng 💎','Giải pháp đặc quyền dài hạn 2 năm cho hệ thống giáo dục, trường liên cấp và đối tác chiến lược.',4990000,7500000,730,1000,'[\"Quản lý không giới hạn đến 1.000 học sinh\", \"Mở khóa toàn diện tất cả các Khối lớp & Chương trình mở rộng\", \"Thời hạn bản quyền dài hạn 2 năm (730 ngày)\", \"Bộ công cụ Quản trị Trường học & Báo cáo nâng cao cho Ban Giám Hiệu\", \"Quyền sử dụng toàn bộ Question Studio soạn đề thi chuyên biệt\", \"Kênh hỗ trợ kỹ thuật và bảo trì hệ thống ưu tiên 24/7\"]',0,4,'2026-09-20 02:30:23','2026-09-20 03:02:55');
