DROP TABLE IF EXISTS `questions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `questions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `practice_test_id` bigint unsigned NOT NULL,
  `external_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `type` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MultipleChoice',
  `title` text COLLATE utf8mb4_unicode_ci,
  `configuration` json DEFAULT NULL,
  `position` smallint unsigned NOT NULL DEFAULT '0',
  `points` smallint unsigned NOT NULL DEFAULT '1',
  `is_published` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `questions_practice_test_id_position_unique` (`practice_test_id`,`position`),
  KEY `questions_practice_test_id_is_published_index` (`practice_test_id`,`is_published`),
  CONSTRAINT `questions_practice_test_id_foreign` FOREIGN KEY (`practice_test_id`) REFERENCES `practice_tests` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=510 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
