INSERT INTO `questions` VALUES (1,1,'tknpy7z1s2t0-i4saw6d23amj','MultipleChoice','Em hãy cho biết, thiết bị nào có bàn di chuột tích hợp để trỏ và nhấp?','[]',0,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:13'),(2,1,'qpl3zxrdl862-ll5meqh46bjv','MultipleChoice','Em hãy cho biết, thuật ngữ nào là phần mềm chạy trên điện thoại hoặc máy tính bảng?','[]',1,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:13'),(3,1,'fdel3hxfnxj3-yhiu5h44gz29','MultipleChoice','Em hãy cho biết, phần mềm nào dưới đây là phần mềm ứng dụng?','[]',2,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:13'),(4,1,'x55ss2svq86w-3uuiuzgzugg8','MultipleChoice','Em hãy cho biết, hình ảnh nào sau đây là một chiếc Laptop?','[]',3,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:13'),(5,1,'lox6nzvywlog-4ikecduo8kd','MultipleChoiceText','Em hãy xác định mỗi tùy chọn là phần cứng hoặc phần mềm.','[]',4,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:13'),(6,1,'cvdigqxm3kqg-qi7vp2y5b3zq','Hotspot','Em muốn tìm một trò chơi đã được cài đặt trên máy tính của mình.\nTrên thanh tác vụ được hiển thị, em nhấp vào đâu để tìm trò chơi?','{\"image_path\": \"/storage/question-assets/imported/q6-5.png\"}',5,1,1,'2026-08-30 23:31:13','2026-09-05 20:45:04'),(7,1,'36vfkuwih48y-zfo5ik8qyl13','MultipleChoice','Em đang học trực tuyến tại thư viện công cộng. Em cần sạc Pin máy tính xách tay để hoàn thành bài tập của mình.\nMột bạn khác đang sạc điện thoại di động ở ổ cắm gần nhất.\nEm nên làm gì để vừa sạc Pin máy tính và vừa tiếp tục học?','[]',6,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:13'),(8,1,'vqa9ez3khm9z-6e5pavfofw37','MultipleResponse','Em hãy cho biết, hai thiết bị nào sau đây là thiết bị ngoại vi? (Chọn 2)','[]',7,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:13'),(9,1,'ndsxr7v0h7lq-59w0u55xm6m','MultipleChoice','Em hãy cho biết, phần mềm nào sau đây là hệ điều hành?','[]',8,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(10,1,'xlze46ybdr1a-d8phd2kagq33','MultipleChoice','Em cần kết nối máy tính bảng với Internet. Em nên sử dụng phương tiện gì dưới đây?','[]',9,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(11,1,'bed8bgze5zxr-t9ais5u8yv6z','MultipleChoice','Em hãy cho biết, loại phần cứng (Hardware) nào gửi dữ liệu đến máy tính?','[]',10,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(12,1,'pvz9h4i7n3cl-3anzapx7d22','Matching','Em hãy ghép nối từng định nghĩa ở cột bên trái sang thuật ngữ tương ứng ở cột bên phải.','[]',11,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(13,1,'hxsvbdwnp2my-3y9f1ytlnxu5','MultipleChoice','Em hãy cho biết, hình ảnh này là loại thiết bị máy tính nào?','[]',12,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(14,1,'r8u8mlsown4c-elzavyc555il','MultipleChoice','An cần sạc điện thoại vào ban đêm để có thể sử dụng nó vào sáng hôm sau.\nTùy chọn nào là nơi an toàn để An giữ điện thoại của mình trong khi đang sạc?','[]',13,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(15,2,'3dbkvktxjhv0-6ra3gwgll2s7','MultipleChoice','Em cần sử dụng máy tính bảng (Tablet) của mình trong giờ học để tham gia vào các bài học. Em nhận thấy rằng thời lượng Pin của máy tính bảng đang trở nên yếu. Bộ sạc của em không hoạt động.\nEm nên làm gì để tiếp tục tham gia trên máy tính bảng của mình?','[]',0,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(16,2,'jxg6k71720or-shq7nv8d01p1','MultipleChoice','Em hãy chọn phát biểu đúng nhất về một phần mềm ứng dụng trên máy tính để bàn?','[]',1,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(17,2,'f9ozeey6q7mv-756zh1wd5mf9','MultipleChoice','Em hãy cho biết, tùy chọn nào sau đây là một tập tin (File)?','[]',2,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(18,2,'4bl4tz19ahyp-3ppsodut6fle','MultipleChoice','Em hãy cho biết, thiết bị đầu vào (Input Device) nào sau đây được tích hợp vào điện thoại thông minh?','[]',3,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(19,2,'w3sr9pr2ufhe-s8tkybiny93r','Hotspot','Em sẽ tìm thấy lệnh Đóng (Close) trên thẻ (Tab) nào sau đây?','{\"image_path\": \"/storage/question-assets/imported/q19-11.png\"}',4,1,1,'2026-08-30 23:31:13','2026-09-05 20:45:04'),(20,2,'ucqdumi4qv1a-jyea1ivjxcv2','MultipleChoice','Em hãy cho biết, máy tính để bàn có thể sử dụng loại thiết bị nào để kết nối Internet?','[]',5,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(21,2,'jhnkslz44nqg-d0lg8au1ng8d','Matching','Em hãy ghép nối từng thuật ngữ ở cột bên phải sang định nghĩa tương ứng ở cột bên trái.','[]',6,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(22,2,'rfruysz4b1t-mhpavlto0eb0','MultipleChoiceText','Em hãy chọn Có nếu phát biểu đó đúng và Không nếu phát biểu đó sai.','[]',7,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(23,2,'8erigt7z3lac-a4rh53m0rqt9','MultipleResponse','Em hãy cho biết, điện thoại thông minh có thể kết nối với Internet bằng những cách nào? (Chọn 2)','[]',8,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(24,2,'lkiykankmigx-q8jzzkc6il5','MultipleChoiceText','Em hãy chọn Có nếu là cách để thoát khỏi ứng dụng trên máy tính để bàn đã được cài đặt và chọn Không nếu không phải.','[]',9,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(25,2,'mck3q94ywb8s-c6890mg0lfpr','Matching','Em hãy ghép thuật ngữ từ cột bên phải sang định nghĩa phù hợp của ở cột bên trái.','[]',10,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(26,2,'eqnvufito68k-jmgnegmm9sdt','MultipleChoiceText','Em hãy cho biết, phương pháp nào sau đây được sử dụng để khởi động ứng dụng đã cài đặt trên máy tính để bàn? Chọn Có nếu đáp án đúng và Không nếu đáp án sai.','[]',11,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(27,2,'l65qrbcgcs8n-dkd6mzai9uin','MultipleResponse','Em hãy cho biết, tùy chọn nào sau đây là những cách có thể sử dụng để kết nối máy tính bảng với Internet? (Chọn 2)','[]',12,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(28,2,'qdfai3i8qd0c-wc1a1mg6feav','MultipleChoice','Em hãy cho biết, tùy chọn nào sau đây là ví dụ về thiết bị đầu vào được tích hợp sẵn trên máy tính?','[]',13,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(29,2,'8bb1urw27ex6-7k3zalj3t0ec','Matching','Em hãy ghép mỗi thuật ngữ ở cột bên phải với định nghĩa phù hợp ở cột bên trái.','[]',14,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(30,3,'drlx3ka0j0ja-6hish8e9lon0','MultipleChoice','Em hãy cho biết, Trolling là gì?','[]',0,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(31,3,'eanr9r968guv-xtx2jrd5s79o','MultipleChoice','Em thấy những bình luận ác ý trong một cuộc trò chuyện trong nhóm trực tuyến.\nEm nên làm gì nếu em là một công dân tốt của thời đại kỉ nguyên số?','[]',1,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(32,3,'mqwiykpbxeh3-y9rk64wusr4r','MultipleChoiceText','Em hãy chọn Đúng nếu là phát biểu đúng về về việc đăng thông tin trên Internet hoặc chọn Sai nếu không phải.','[]',2,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(33,3,'uqgvcphcr3z7-8o1ndr2v9nlg','MultipleChoice','Em hãy cho biết, việc ai đó sử dụng công nghệ để gây ác ý với người khác được gọi là gì?','[]',3,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(34,3,'xtzsfv4c5dg1-nvrutht88bf9','MultipleChoice','Em đang trò chuyện trực tuyến với một người bạn và một cuộc tranh cãi nảy sinh.\nEm nên làm gì?','[]',4,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(35,3,'5fq5a94ulfbx-ch94f0t4r26c','MultipleChoice','Một người lạ đã đăng bình luận tiêu cực trên mạng xã hội về bạn An. Bạn ấy đã xóa bình luận nhưng người đó lại tiếp tục viết những bình luận ác ý hơn.\nEm hãy cho biết hành động của người lạ đó được gọi là gì?','[]',5,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(36,3,'adrn1mowiwpv-twj7sjwm3e1r','MultipleChoice','Em hãy cho biết, quyền riêng tư kĩ thuật số là gì?','[]',6,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(37,3,'s9dhfkbendd-dmpes0tlxeah','MultipleChoice','Em hãy cho biết, tùy chọn nào đại diện cho đặc điểm của công dân kĩ thuật số tốt?','[]',7,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(38,3,'dfv25l2gu350-4z38a8i4d614','MultipleChoice','Trong các tùy chọn sau, tùy chọn nào là ví dụ về bắt nạt trực tuyến?','[]',8,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(39,3,'5ifvueiqtxzi-tluy1bdfnbpk','MultipleChoice','Em nhập tên của mình vào một công cụ tìm kiếm và kết quả tìm kiếm bao gồm các ảnh mà em đã xóa khỏi trang Web nơi em đã đăng trước đây. Điều này có nghĩa là gì?','[]',9,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(40,3,'kv28qc7w9tjm-almujf5f4zh7','MultipleResponse','Em hãy cho biết, tùy chọn nào sau đây là một phần của dấu chân kĩ thuật số (Digital Footprint) của em? (Chọn 3)','[]',10,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(41,3,'w868oev4791n-cv6s63qtuafr','MultipleChoice','Em hãy cho biết, những hành động nào là một công dân kỹ thuật số tích cực?','[]',11,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(42,3,'l2blscgmz5c2-r0jmvtx8kw95','Matching','Em hãy ghép mỗi thuật ngữ ở cột bên phải với định nghĩa tương ứng ở cột bên trái.','[]',12,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(43,3,'renu08mkqyqh-ybxa3lt0vbzg','MultipleChoice','Em hãy cho biết, những hành động nào là một công dân kỹ thuật số tiêu cực?','[]',13,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(44,3,'uumz4286lcsn-7p5k9q4azhit','MultipleChoiceText','Em hãy chọn Đúng nếu là phát biểu đúng và chọn Sai nếu là phát biểu sai.','[]',14,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(45,4,'1peofhkrocym-nd4bqcf9qok5','MultipleChoice','Em đang nghiên cứu trực tuyến cho một bài tập về đại dương. Giáo viên đã hướng dẫn em bao gồm ít nhất ba sự kiện và không có ý kiến. Theo em, tùy chọn nào sau đây là một ý kiến?','[]',0,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(46,4,'6tbb554hgk2m-mfa976tx530e','MultipleChoice','Em hãy cho biết, tùy chọn nào dưới đây cho phép truy cập và duyệt thông tin trên Internet?','[]',1,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(47,4,'1d9x122ec9hm-931kl8qsuet0','MultipleChoice','Em hãy cho biết, công cụ nào của trình duyệt cho phép truy cập vào các trang Web yêu thích?','[]',2,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:14'),(48,4,'a98qy9k7nqpf-pgihm7lcw8hx','Matching','Em hãy ghép mỗi thuật ngữ ở cột bên trái với định nghĩa tương ứng ở cột bên phải.','[]',3,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:15'),(49,4,'xd9245o74nr4-9d6jo3cz9xen','MultipleChoice','Em hãy cho biết, khu vực ở đầu cửa sổ trình duyệt hiển thị URL trang Web được gọi là gì?','[]',4,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:15'),(50,4,'g6d25kfkkzwu-xwaiejjfmcd7','MultipleChoice','Theo em, cách nào nhanh nhất để lưu trang Web đang xem để có thể quay lại sau?','[]',5,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:15'),(51,4,'oejo7dbs1uc1-o9713agjf2if','MultipleChoice','Em thường tìm thấy điều gì trong ứng dụng máy tính để bàn và trên các trang Web?','[]',6,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:15'),(52,4,'coxfs3be42k4-55jwto4jl9h8','Hotspot','Em nên nhấp vào biểu tượng nào để đóng (Close) cửa sổ trình duyệt hiển thị?','{\"image_path\": \"/storage/question-assets/imported/q52-13.png\"}',7,1,1,'2026-08-30 23:31:13','2026-09-05 20:45:04'),(53,4,'2so6nnn82gf7-5tsalxxp39wd','Hotspot','Em sẽ nhấp vào đâu để truy cập các trang khác của trang Web Net PC trong cửa sổ trình duyệt?','{\"image_path\": \"/storage/question-assets/imported/q53-14.png\"}',8,1,1,'2026-08-30 23:31:13','2026-09-05 20:45:04'),(54,4,'1rh6uwp4hvof-p6uimlkjjgun','MultipleChoice','Một giáo viên bảo học sinh của mình nghiên cứu một chủ đề trên máy tính bảng của họ trong 30 phút tiếp theo. Khi giáo viên hỏi một học sinh xem bạn ấy có thực hiện nghiên cứu hay không, bạn ấy nói có. Làm thế nào giáo viên có thể tìm ra liệu học sinh có nói sự thật hay không?','[]',9,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:15'),(55,4,'tynd6cyod1if-nagjehia0gc4','Hotspot','Trên trang Web được hiển thị, em nên nhập URL mới vào đâu?','{\"image_path\": \"/storage/question-assets/imported/q55-15.png\"}',10,1,1,'2026-08-30 23:31:13','2026-09-05 20:45:04'),(56,4,'21x9qrpk7ktp-4v8ohp26jae3','MultipleChoice','Em có thể lưu gì trong tính năng Bookmarks/Favorites của trình duyệt Web?','[]',11,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:15'),(57,5,'dgkmj2xxh93-cjk0if2fq6m6','MultipleChoice','Vy thích đọc các bài báo trực tuyến. Cô ấy chỉ muốn đọc các bài báo dựa trên sự thật, không phải ý kiến.\nCâu hỏi nào có thể giúp Vy xác định các bài báo dựa trên thực tế?','[]',0,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:15'),(58,5,'pnxmt5p7ih0-7ckqu67m3m0f','MultipleChoiceText','Em đang tìm kiếm một nơi để đi với các bạn cùng lớp. Em đọc một bài đánh giá trực tuyến cho một nhà hàng nghe có vẻ tốt. Em không chắc liệu có nên tin vào tuyên bố của người đánh giá hay không.\nEm hãy chọn Thực tế hoặc chọn Ý kiến với mỗi phát biểu sau.','[]',1,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:15'),(59,5,'m0ssz3hts06v-z0949kkcnsn6','Matching','Em hãy ghép mỗi thuật ngữ ở cột bên phải với định nghĩa tương ứng ở cột bên trái.','[]',2,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:15'),(60,5,'ivceya6fb7i9-77jqunswvfws','MultipleResponse','Em hãy chọn những thành phần nào thuộc giao diện của trình duyệt Web? (Chọn 3)','[]',3,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:15'),(61,5,'h0zab7jmem4s-xvmnkou77bxy','MultipleChoice','Em hãy cho biết, URL là gì?','[]',4,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:15'),(62,5,'wqqvki31re6m-yz94z5fpp8d2','MultipleChoice','Theo em, cách nào là nhanh nhất để lưu một trang Web để em có thể quay lại sau này?','[]',5,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:15'),(63,5,'8f5kvsgv42c6-x8i9dtj1kxgg','MultipleChoice','Em hãy cho biết, tùy chọn nào là ví dụ về một trang Web (Webpage)?','[]',6,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:15'),(64,5,'aarv5mt0sy1k-dozmeg67p61p','Matching','Em hãy cho biết, tùy chọn nào là ví dụ về một trang Web (Webpage)?','[]',7,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:15'),(65,5,'f0ncs1danzp6-ufvvu5ki08ys','MultipleChoice','Em hãy cho biết, em có thể tìm thấy URL của một trang Web ở đâu để có thể sao chép và dán?','[]',8,1,1,'2026-08-30 23:31:13','2026-09-05 20:21:15'),(66,5,'fajyr1uhthf6-hw6cf2i8rjce','MultipleResponse','Em có thể sử dụng những thông tin nào để kiểm tra độ tin cậy của mộ