  `phone` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Số điện thoại liên hệ',
  `email` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Email liên hệ',
  `message` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Nội dung câu hỏi / tư vấn',
  `admin_reply` text COLLATE utf8mb4_unicode_ci COMMENT 'Nội dung phản hồi từ Admin',
