INSERT INTO `support_messages` VALUES (1,'Cô Hoàng Mai (TH Chu Văn An)','0987654321','hoangmai.cvan@gmail.com','Cho mình hỏi thông tin về gói bản quyền IC3 GS6 khối 3, 4, 5 cho trường học với ạ! Trường mình có 12 lớp cần cấp tài khoản cho khoảng 400 học sinh.','👍','2026-09-17 09:17:55','replied','127.0.0.1','2026-09-17 16:04:54','2026-09-17 16:17:55'),(2,'Thầy Nguyễn Văn An (THCS Hòa Bình)','0912345678','nguyenvanan.gv@gmail.com','Mình vừa đăng ký Gói Tiêu Chuẩn 990.000đ nhưng chuyển khoản quên ghi mã đơn hàng, nhờ Admin kiểm tra và kích hoạt giúp mình với nhé!',NULL,NULL,'pending','127.0.0.1','2026-09-17 16:04:54','2026-09-18 02:23:48'),(3,'Thầy Trần Quốc Tuấn (Trường Quốc Tế Á Châu)','0938889999','quoctuan.edu@gmail.com','Phần mềm có hỗ trợ xuất file điểm kiểm tra định kỳ ra định dạng Excel theo mẫu của Bộ GD&ĐT không bạn ơi?','Dạ em chào Thầy/Cô! Em là chuyên viên hỗ trợ IC3 Quest. Em xin gửi thông tin chi tiết gói bản quyền nhé ạ!','2026-09-17 09:42:34','replied','127.0.0.1','2026-09-17 16:04:54','2026-09-17 16:42:34'),(4,'hh','hh',NULL,'d','hi\nsao á?','2026-09-17 17:46:50','responded','127.0.0.1','2026-09-17 17:08:08','2026-09-18 00:46:50'),(5,'test sever','0345151438',NULL,'alo ạ cần mau gói ạ',NULL,NULL,'pending','127.0.0.1','2026-09-19 15:17:59','2026-09-19 15:17:59'),(6,'test sever','0345151438',NULL,'dạ','sao ạ','2026-09-19 08:22:30','replied','127.0.0.1','2026-09-19 15:22:01','2026-09-19 15:22:30'),(7,'Thay Hoang','0345151438',NULL,'hu admim','dạ','2026-09-19 08:26:20','replied','127.0.0.1','2026-09-19 15:26:03','2026-09-19 15:26:20'),(8,'Thay Hoang','0345151438',NULL,'cần tư vấn ạ',NULL,NULL,'pending','127.0.0.1','2026-09-19 15:26:31','2026-09-19 16:27:45'),(9,'Cô Mai Linh (GV 3A1)','teacher@ic3.test','teacher@ic3.test','Kính gửi Ban Quản Trị, tôi muốn gửi yêu cầu cấp thêm số lượng học sinh / mở rộng khối lớp giảng dạy cho tài khoản của mình. Nhờ Ban Quản Trị hỗ trợ giúp tôi với ạ!\nKính gửi BQT, tôi muốn gửi yêu cầu cấp thêm số lượng học sinh cho lớp.','dạ','2026-09-20 04:14:46','pending','127.0.0.1','2026-09-20 04:06:27','2026-09-20 04:15:33');
